    "factor_updates": [
      {
        "factor": "Persistent CDU lead in late pre-election polls",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Polls in February 2026 show CDU around 27–31% versus Greens 20–27%; translates into a higher likelihood of CDU seat plurality under MMP."
      },
      {
        "factor": "CDU explicitly projected as the largest party in late polls",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Projects CDU as largest party, reinforcing seat advantage through distribution rules."
      },
      {
        "factor": "Greens closing the gap against CDU",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Greens near CDU levels in some polls compresses the margin and raises risk of not obtaining most seats."
      },
      {
        "factor": "AfD maintains sizable share (~19–21%)",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "AfD's strength siphons votes from both blocs, reducing probability of CDU seat majority."
      },
      {
        "factor": "Electoral-system amplification for the largest party",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "BW's 120-seat, 5% threshold system tends to amplify the lead into more seats for the leading party when lead exists."
      }
    ],
    "synthesis_rationale": "Starting from a 0.65 anchor, the updates collectively push the posterior toward 0.87. Strong signal from CDU polling lead and explicit largest-party projections; concurrent Greens/AfD risks and amplification effects are accounted for as downward or downward/up adjustments. Calibration aligns with observed historical variability in BW outcomes and acknowledges turnout and regional patterns as residual uncertainty."
  }
}

